        add("elementalcraft.landing", "$(thing)ElementalCraft$() is a magic mod based around the 4 $(thing)elements$(): $(thing)fire$(), $(thing)water$(), $(thing)earth$() and $(thing)air$().$(br2)You can you can also find more information on the $(l:https://wiki.elementalcraft.org/)wiki$().");

        addPatchouliCategory("basics", "Basics", "Basics and early-game mechanics.");
        addPatchouliCategory("sources", "Sources", "$(ec:source)Sources$() are naturally occurring spots where $(thing)elements$() converge.");
        addPatchouliCategory("element_production", "Element Production", "$(thing)Element$() can either be extracted from $(ec:source)sources$(), t(his is the easiest way. Or you can use an synthesizers if you cannot find sources or they a are unavailable.");
        addPatchouliCategory("instruments", "Instruments", "$(thing)Instruments$() are the main crafting tools in $(thing)ElementalCraft$().$(br)They consume $(thing)elements$() and are required to be on top of a $(ec:container)Container$().");
        addPatchouliCategory("crafting", "Crafting", "Here is everything you need to know about $(thing)Crafting$().");
        addPatchouliCategory("shrines", "Shrines", "$(thing)Shrines$() are powerful tools that channel $(thing)elements$() in the world around them to act on it.");
        addPatchouliCategory("shrine_upgrades", "Shrine upgrades", "You can craft $(thing)shrine upgrades$() to increase the power of your $(thing)shrines$(). Those upgrades can only be placed at specific places around the $(thing)shrine$().$(br)Upgrades cover a wide range of bonuses from $(thing)speed$(), $(thing)reduce consumption$(), $(thing)range$()... or specific ones like $(thing)silk touch$() or $(thing)fortune$() for the $(l:shrines/oreshrine)ore shrine$().");
        addPatchouliCategory("pipes", "Element transfer", "The ability to move elements using pipes.");
        addPatchouliCategory("advanced", "Advanced", "Advanced and powerful late-game tools.");
        addPatchouliCategory("spells", "Spells", "Spells allow you to directly affect the world around you.$(br)You can always use a spell, but it will break if the required resource isn't present. To provide them you need to have an $(ec:holder)element holder$() of the same element.");
        addPatchouliCategory("jewels", "Jewels", "$(thing)Jewels$() gives you passive bonuses at the cost of element from your $(ec:holder)element holder$().$(br)You can have this effect by placing it on a piece of gear using an anvil.");

        addPatchouliEntry("sources", "Sources");
