        addPatchouliEntry("element_holders", "Element Holders");
        addPatchouliEntry("casting_spells", "Casting spells");
        addPatchouliEntry("using_shrines", "Using Shrines");

        addPatchouliPages("inert_crystal", "To get $(item)Inert Crystal$() start digging underground and mine $(item)Inert Crystal Ore$().");
        addPatchouliPages("contained_crystal", "$(item)Contained Crystals$() are the main components of $(thing)instruments$().$(br)By coating an $(item)Inert Crystal$() with $(thing)gold$() you are able to prevent it from being altered by $(thing)elements$() without losing its ability to interact with them.");
        addPatchouliPages("whiterock", "$(item)Whiterock$() is $(thing)earth infused$() $(item)stone$().$(br)It is used in the crafting of advanced $(thing)instruments$() and $(thing)shrines$().$(br)To get it simply put $(item)stone$() in an $(ec:infuser)infuser$().");
        addPatchouliPages("springaline", "$(thing)Springaline$() is a very old material, legends say $(ec:source)sources$() spring from it.$(br)It can be recreated in a $(ec:binder)binder$() using ametysts, nether quartz and water crystals. Once you get your first shard its easier to create springaline clusters in your $(ec:binder)binder$() and mine them with a fortune pickaxe or grind them using a $(l:instruments/water_mill_grindstone)water mill grindstone$() or an $(l:instruments/air_mill_grindstone)air mill grindstone$().");
        addPatchouliPages("fire_lens", "The $(item)Fire lens$() is a piece of glass that can channel sunlight into elemental fire.");
        addPatchouliPages("gems", "$(item)Element gems$() are created from $(item)diamonds$() in an infuser and then refined with a $(l:instruments/crystallizer)gem crystallizer$(). There are three qualities of $(l:basics/gems)gems$(): crude, fine and pristine.");
        addPatchouliPages("pure_infuser", "The $(item)Pure Infuser$() is the most powerful crafting tool. It uses $(item)pedestals$() to channel all four $(thing)elements$() into a single item.$(br)To operate, it needs to be circled with each of the four $(item)pedestals$(), each being provided with the correct $(thing)element$() using $(ec:pipe)improved pipes$().$(br)Once this setup is done, you can start crafting by putting the correct $(item)ingredient$() on each $(thing)pedestal$() and the main one on the $(thing)pure infuser$().$(br2)Can be upgraded with up to three $(ec:rune)Runes$() and one for pedestals.");

        addPatchouliPages("sources",
                "$(thing)Sources$() are naturally occurring spots where $(thing)elements$() converge.$(br2)It's strongly recommended to explore a bit and find at least one $(thing)source$() for each $(thing)element$().$(br2)Be careful though as if you extract too much element from a source it will enter a recovery state. In this state you can no longer extract from the source until it fully recovers its capacity.$(br)It is also recommended to mark their spots to find them easier again when you need them.",
                "$(thing)Sources$() have natural affinity to different biomes or world areas.$(br)$(thing)Fire$() is found in dry biomes and in the nether.$(br)$(thing)Water$() is found in wet biomes and over bodies of water.$(br)$(thing)Earth$() is fount in rock biomes and underground.$(br)$(thing)Air$() is found over tall biomes or plains, up in the sky and in the end.",
                "An $(thing)Air Source$() found naturally.");
        addPatchouliPages("source_traits",
                "$(thing)Source traits$() are an ensemble of traits that define how $(ec:source)sources$() behave. This affects things like the amount they can hold or the speed it takes for them to recover. You can see source traits by using a $(l:sources/source_analysis_glass)source analysis glass$().",
                "$(thing)Capacity$(): The element capacity of the source, the bigger the capacity the longer it will take to exhaust and replenish the source.$(br)$(e)Diurnal$(): Increased recovery speed during the day, decreased recovery speed during the night.$(br)$(1)Nocturnal$(): Increased recovery speed during the night, decreased recovery speed during the day.",
                "$(9)Generous$(): Increased extraction speed from the source.$(br)$(c)Selfish$(): Decreased extraction speed from the source.$(br)$(9)Thrifty$(): Decreased element loss when extracting from the source.$(br)$(c)Wasteful$(): Increased element loss when extracting from the source.$(br)$(9)Fertile$(): Reduced element cost of $(l:sources/source_seeds)source seeds$().");
        addPatchouliPages("source_analysis_glass", "The $(item)Source Analysis Glass$() can be used to analyse $(ec:source)sources$(). It will show you what $(ec:source_traits)traits$() the source has.$(br)Every analysis will consume a $(l:basics/springaline)Springaline shard$() from your inventory, so you need to have at least one. You can either analyse a source by right-clicking it with the glass or from a receptacle by placing it in the upper right slot of the analysis GUI.");
        addPatchouliPages("empty_receptacle", "The $(item)Source Receptacle$() is a powerful tool that allow you to move $(ec:source)source$().$(br)By using it on a source yon can pick it up, you can then place it back where ever you want. Doing so will consume the receptacle.");
        addPatchouliPages("source_stabilizer", "The $(item)source stabilizer$() is an item that can be used on $(ec:source)sources$(). It prevents them from being replaced by blocks. It also slightly increases the source recovery rate.");
        addPatchouliPages("source_breeder", "The $(item)source breeder$() is the strongest tool that can act on $(ec:source)sources$(). It has the ability to create new sources from existing ones. The created source will inherit $(ec:source_traits)traits$() from the parent sources.$(br)It needs a $(l:sources/source_seeds)source seed$() to create a new source.$(br2)Can be upgraded with up to three $(ec:rune)Runes$() and one for pedestals.");
        addPatchouliPages("source_seeds", "The $(item)source seeds$() are used in the $(l:sources/source_breeder)source breeder$() to create new $(ec:source)sources$().");

        addPatchouliPages("container", "The $(item)Element Container$() is a an $(thing)element$() storage, containing more $(thing)element$() than the $(ec:small_container)Small Container$(), and it is compatible with all $(thing)instruments$().");
        addPatchouliPages("rudimentary_extractor", "Use a $(item)Rudimentary Element Extractor$() to extract $(thing)elements$() from $(ec:source)sources$().$(br2)To do so place the $(item)Extractor$() above a $(ec:container)Container$() and below the $(ec:source)source$() you want to extract from.$(br2)Can be upgraded with one $(ec:rune)Rune$().");
        addPatchouliPages("infuser", "Now that you can extract $(thing)elements$(), it's time to infuse them.$(br2)To do so you need an $(item)Infuser$() on top of a $(ec:container)Container$().$(br)Don't forget to connect it to the $(ec:extractor)Extractor$()'s $(ec:container)Container$() with a $(ec:pipe)pipe$().$(br2)By placing $(item)tools$() in an $(item)element infuser$() you can add effects to them. It's a good way to get early enchantments on tools. You can change the infusion on a tool at any time by infusing it with another element.$(br2)Can be upgraded with one $(ec:rune)Rune$().");
        addPatchouliPages("small_container", "The $(item)Small Element Container$() is a simple $(thing)element$() storage for providing $(thing)elements$() to $(thing)instruments$().$(br2)All $(thing)instruments$() need to be placed on top of a $(item)Container$() to operate.$(br)The $(item)Small Element Container$() can only work with $(ec:extractor)Extractors$() and $(ec:infuser)Infusers$().$(br)You can also transfer $(thing)elements$() from one $(item)Container$() to another using $(ec:pipe)pipes$().");
        addPatchouliPages("binder", "The $(item)Binder$() is one of the most important $(thing)Instruments$(). It channels $(thing)elements$() to combine multiples items together.$(br)Be careful because the order in which you put the items is important, you need to put them clockwise from the top.$(br)As for any other $(thing)Instrument$(), the $(item)Binder$() needs to be on top of a $(ec:container)Container$() but not a $(ec:small_container)Small Container$().$(br2)Can be upgraded with up to two $(ec:rune)Runes$().");
        addPatchouliPages("extractor", "The $(item)Improved Element Extractor$() is an improvement over the version of the $(ec:rudimentary_extractor)Rudimentary Element Extractor(). It extract $(thing)elements$() faster.$(br)As for any other $(thing)Instruments$(), the $(item)Improved Extractor$() needs to be on top of a $(ec:container)Container$() but not a $(ec:small_container)Small Container$().$(br2)Can be upgraded with up to three $(ec:rune)Runes$().");
        addPatchouliPages("cracking_earth_synthesizer", "The $(item)Cracking Earth Synthesizer$() allows you to harvest $(thing)earth$() by breaking nearby blocks. It needs to be placed on top of a $(ec:container)Container$().$(br2)Can be upgraded with one $(ec:rune)Rune$().");
        addPatchouliPages("combustion_fire_synthesizer", "The $(item)Combustion Fire Synthesizer$() allows you to harvest $(thing)fire$() by burning fuel. It needs to be placed on top of a $(ec:container)Container$().$(br2)Can be upgraded with one $(ec:rune)Rune$().");
        addPatchouliPages("draining_water_synthesizer", "The $(item)Draining Water Synthesizer$() allows you to harvest $(thing)water$() by draining water from player's hunger bar, you need to right click it to use it. It needs to be placed on top of a $(ec:container)Container$().$(br2)Can be upgraded with one $(ec:rune)Rune$().");
        addPatchouliPages("vibration_air_synthesizer", "The $(item)Vibration Air Synthesizer$() allows you to harvest $(thing)air$() from sound vibration. It needs to be placed on top of a $(ec:container)Container$().$(br2)Can be upgraded with one $(ec:rune)Rune$().");
        addPatchouliPages("solar_fire_synthesizer", "The $(item)solar element synthesizer$() allows you to harvest $(thing)fire$() from the sun light. It needs to see the sky and only works during the day. You also need to provide a $(l:basics/lenses)lens$() to make it work.$(br2)To do so place the $(item)solar element synthesizer$() above a $(ec:container)Container$().$(br2)Can be upgraded with up to two $(ec:rune)Runes$().");
        addPatchouliPages("culinary_water_synthesizer", "The $(item)Culinary Water Synthesizer$() allows you to harvest $(thing)water$() by consuming food. It needs to be placed on top of a $(ec:container)Container$().$(br2)Can be upgraded with up to two $(ec:rune)Runes$().");
        addPatchouliPages("sculk_cracking_earth_synthesizer", "The $(item)Sculk Cracking Earth Synthesizer$() allows you to harvest $(thing)earth$() by breaking nearby skulk. It needs to be placed on top of a $(ec:container)Container$().$(br2)Can be upgraded with up to two $(ec:rune)Runes$().");
        addPatchouliPages("air_mill_synthesizer", "The $(item)Air Mill Synthesizer$() allows you to harvest $(thing)air$() by using an air mill. It needs to be placed on top of a $(ec:container)Container$().$(br2)Can be upgraded with up to two $(ec:rune)Runes$().");
        addPatchouliPages("crystallizer", "The $(item)Gem crystallizer$() allows you to refine an $(l:basics/gems)elemental gem$(). $(br)To use it place the $(item)gem$() first and then the $(thing)crystal$().$(br2)Can be upgraded with up to three $(ec:rune)Runes$().");
        addPatchouliPages("inscriber", "The $(item)Rune Inscriber$() is used to create $(ec:rune)Runes$().$(br)At the difference of other $(thing)instruments$() it needs to be right-clicked multiple times with a $(item)chisel$() to operate.$(br2)Can be upgraded with up to three $(ec:rune)Runes$().");
        addPatchouliPages("enchantment_liquefier", "The $(item)Water Enchantment Liquefier$() allows you to transfer enchantment from an item to another.$(br)It has a small chance to reduce the enchantment level in the process, the rarer the enchantment the more element it will cost and will have a greater chance to downgrade.$(br2)Can be upgraded with up to three $(ec:rune)Runes$() including luck ones.");
        addPatchouliPages("firefurnace", "The $(item)Fire Furnace$() smelts items by using $(thing)fire element$() instead of fuel.$(br)As for any other $(thing)Instrument$(), the $(item)Fire Furnace$() needs to be on top of a $(ec:container)Container$(). It consumes $(thing)fire$().$(br2)Can be upgraded with up to two $(ec:rune)Runes$().");
        addPatchouliPages("fireblastfurnace", "The $(item)Fire Blast Furnace$() is the $(item)Blast Furnace$() variant of the $(ec:firefurnace)Fire Furnace$().$(br)As for any other $(thing)Instrument$(), the $(item)Fire Blast Furnace$() needs to be on top of a $(ec:container)Container$() but not a $(ec:small_container)Small Container$(). It consumes $(thing)fire$().$(br2)Can be upgraded with up to three $(ec:rune)Runes$().");
        addPatchouliPages("improved_extractor", "The $(item)Improved Extractor$() is an advanced version of the $(ec:extractor)Extractor$(). It extract $(thing)elements$() faster.$(br)As for any other $(thing)Instrument$(), the $(item)Improved Extractor$() needs to be on top of a $(ec:container)Container$() but not a $(ec:small_container)Small Container$().$(br2)Can be upgraded with up to three $(ec:rune)Runes$().");
        addPatchouliPages("purifier", "The $(item)Purifier$() takes $(item)ores$() and purifies them to create $(item)Pure ores$() at a ratio of one to two. You can then smelt them into $(item)ingots$() in any $(item)Furnace$().$(br)As for any other $(thing)Instrument$(), the $(item)purifier$() needs to be on top of a $(ec:container)Container$() but not a $(ec:small_container)Small Container$().$(br)It consumes $(thing)earth$().$(br2)Can be upgraded with up to three $(ec:rune)Runes$() including luck ones.");
        addPatchouliPages("water_mill_grindstone", "The $(item)Water mill grindstone$() allows you to grind down items like $(item)stone$() to $(item)gravel$().$(br)As for any other $(thing)Instrument$(), the $(item)water mill grindstone$() needs to be on top of a $(ec:container)Container$().$(br)It consumes $(thing)water$().$(br2)Can be upgraded with up to three $(ec:rune)Runes$() including luck ones.");
        addPatchouliPages("air_mill_grindstone", "The $(item)Air mill grindstone$() allows you to grind down items like $(item)stone$() to $(item)gravel$(), it is faster than a $(l:instruments/water_mill_grindstone)water mill grindstone$().$(br)As for any other $(thing)Instrument$(), the $(item)air mill grindstone$() needs to be on top of a $(ec:container)Container$() but not a $(ec:small_container)Small Container$().$(br)It consumes $(thing)air$().$(br2)Can be upgraded with up to three $(ec:rune)Runes$() including luck ones.");
        addPatchouliPages("water_mill_wood_saw", "The $(item)Water mill wood saw$() allows you to cut down items mainly $(item)wood$() to more refined variant.$(br)As for any other $(thing)Instrument$(), the $(item)water mill wood saw$() needs to be on top of a $(ec:container)Container$().$(br)It consumes $(thing)water().$(br2)Can be upgraded with up to three $(ec:rune)Runes$() including luck ones.");
        addPatchouliPages("air_mill_wood_saw", "The $(item)Air mill wood saw$() allows you to cut down items mainly $(item)wood$() to more refined variant, it is faster than a $(l:instruments/water_mill_wood_saw)water mill wood saw$().$(br)As for any other $(thing)Instrument$(), the $(item)air mill wood saw$() needs to be on top of a $(ec:container)Container$() but not a $(ec:small_container)Small Container$().$(br)It consumes $(thing)air().$(br2)Can be upgraded with up to three $(ec:rune)Runes$() including luck ones.");
        addPatchouliPages("binder_improved", "The $(item)Improved Element Binder$() works like a $(ec:binder)Binder$() and $(ec:infuser)Infuser$() meaning it can do either binding or infusion at a faster rate.$(br)As for any other $(thing)Instrument$(), the $(item)improved binder$() needs to be on top of a $(ec:container)Container$() but not a $(ec:small_container)Small Container$().$(br2)Can be upgraded with up to three $(ec:rune)Runes$().");
        addPatchouliPages("reservoirs", "The $(item)Element Reservoir$() is a advanced $(thing)element$() storage, containing more $(thing)element$() than the $(ec:container)Container$(). It is compatible with all $(thing)instruments$(). There are four different variants, one for each element.");
        addPatchouliPages("diffuser", "The $(item)Element diffuser$() fills the $(ec:holder)element holders$() of nearby players, the $(item)improved diffuser$() needs to be on top of a $(ec:container)Container$() but not a $(ec:small_container)Small Container$().$(br2)Can be upgraded with up to three $(ec:rune)Runes$().");

        addPatchouliPages("element_pipe", "$(item)Pipes$() are used to transport $(thing)elements$() across distances. Their main use is to provide $(thing)instruments$() with the required $(thing)element$().$(br2)You can configure a $(item)pipe$() by right-clicking a section or the core to change it from $(thing)connected$(), $(thing)disconnected$(), $(thing)insert$() or $(thing)extract$().$(br2)$(item)Pipes$() exist in three tiers: impaired, normal and improved. You can upgrade all connected pipes if you right-click one holding a pipe of the next tier.");
        addPatchouliPages("cover_frame", "The $(item)pipe cover frame$() allows you to hide a $(ec:pipe)pipe$() behind a block. Use it on a pipe (preferably while sneaking), then right click it with the block you want to hide it with.$(br)You can hide frames and show pipes by holding a pipe, a frame or having an empty hand.");
        addPatchouliPages("pipe_priority_rings", "$(item)Pipe priority rings$() are an upgrade you can put on a $(ec:pipe)pipe$() section to encourage $(thing)elements$() flow in a specific direction.");
        addPatchouliPages("element_valve", "The $(item)Element valve$() is an upgrade you can put on a $(ec:pipe)pipe$() section to only let $(thing)elements$() flow when it receives a redstone signal.");
        addPatchouliPages("element_beam", "The $(item)Element beam$() is an upgrade you can put on two $(ec:pipe)pipe$() sections facing each other allowing element transfer between them for a short range.");
        addPatchouliPages("element_pump", "The $(item)Element pump$() is an upgrade you can put on a $(ec:pipe)pipe$() extracting section to greatly improve its extracting speed at the cost of wasting a portion of the transferred elements.$(br2)Can be upgraded with up to three speed only $(ec:rune)Runes$().");

        addPatchouliPages("element_holders", "$(item)Element Holders$() can hold $(thing)elements$() for transport or for use by $(thing)spells$().$(br)To fill them hold right-click on a $(ec:source)source$() of the same $(thing)element$() type. You can also transfer $(thing)element$() back to a receiver by holding right-click on it.");
        addPatchouliPages("purerock", "$(item)Pure Rock$() is an extremely strong stone that is able to resist some of the most powerful blasts, even a $(thing)Wither$().");
        addPatchouliPages("instrument_retriever", "The $(item)Instrument Output Retriever$() is a finely-tweaked machine that can interact with $(thing)instruments$() and handle their output for themselves, allowing you to extract their output upon crafting and store it in a $(item)chest$(), for example.$(br2)You can reorient its input and output by right-clicking.");
        addPatchouliPages("elemental_firefuel", "The $(item)Elemental Firefuel$() is an advanced form of fuel that does not get consumed if there is nothing to cook.");
        addPatchouliPages("sorter", "The $(item)Ordered Sorter$() uses the advanced properties of swift alloy to insert specific items in a specific order into any $(thing)instrument$() or $(thing)chest$().$(br)You can add a new item to the order list by right-clicking the middle part.$(br)You can reorient its input and output by right-clicking.$(br2)Can be upgraded with up to three speed only $(ec:rune)Runes$().");
        addPatchouliPages("runes", "$(thing)Runes$() are infused with element power that can be transferred to $(thing)instruments$() to boost their properties.$(br)They are created using an $(l:instruments/inscriber)inscriber$() and a chisel.$(br)You can simply add them by right clicking the instrument with the rune, and remove them either with a chisel or by breaking the instrument.");
        addPatchouliPages("pure_element_holder", "The $(item)Pure element holder$() is an improved version of the $(ec:holder)element holder$(). It can store all four $(thing)elements$() at once and in a way bigger quantity.");

        addPatchouliPages("using_shrines",
                "Shrines require element to be $(ec:pipe)piped$() in to operate. If the source doesn't find the action to perform it won't consume any element.$(br2)You can display the range of any shrine for 30 secs by shift right clicking on it with an empty hand.",
                "You can see if the shrine is currently running by looking at the check at the bottom right of the element gauge:",
                "The shrine is running",
                "The shrine is running but did not find anything to do",
                "The shrine is out of element");
        addPatchouliPages("firepylon", "The $(item)Fire Pylon$() is a $(thing)Shrine$() that sets nearby $(thing)creatures$() on fire.$(br2)It consumes $(thing)fire element$().");
        addPatchouliPages("oreshrine", "The $(item)Ore Shrine$() excavates $(thing)ores$() underneath it leaving only $(item)stone$() where the $(thing)ore$() was.$(br2)It consumes $(thing)earth element$().");
        addPatchouliPages("melting_shrine", "The $(item)Lava Shrine$() melts $(item)basalt$() above it into $(item)lava$().$(br2)It consumes $(thing)fire element$().");
        addPatchouliPages("sweetshrine", "The $(item)Sweet Shrine$() periodically refills hunger. It can also boost nearby $(thing)bees$() production instead if you upgrade it with a $(l:shrine_upgrades/shrine_upgrade_nectar)Nectar shrine upgrade$().$(br2)It consumes $(thing)water element$().");
        addPatchouliPages("vacuumshrine", "The $(item)Vacuum Shrine$() pulls nearby $(item)items$() towards itself and stores them in the container below it.$(br2)It consumes $(thing)air element$().");
        addPatchouliPages("growthshrine", "The $(item)Growth Shrine$() accelerates $(thing)crop$() growth from its level up to 3 blocks above it. To grow $(thing)crops$() that cannot grow with $(item)bonemeal$() you need to upgrade the $(item)growth shrine$() with a $(l:shrine_upgrades/shrine_upgrade_boneless_growth)boneless growth shrine upgrade$().$(br2)It consumes $(thing)water element$().");
        addPatchouliPages("harvestshrine", "The $(item)Harvest Shrine$() harvests $(thing)crops$() below it.$(br2)It consumes $(thing)earth element$().");
        addPatchouliPages("lumbershrine", "The $(item)Lumber Shrine$() cuts down $(thing)trees$() and $(thing)leaves$() above and around it.$(br2)It consumes $(thing)earth element$().");
        addPatchouliPages("overloadshrine", "The $(item)Overload Shrine$() boosts the speed of the $(item)block$() its facing, it cannot boost other shrines.$(br2)It consumes $(thing)air element$().");
        addPatchouliPages("enderlockshrine", "The $(item)Ender Lock Shrine$() channels $(thing)water$() through the ender matrix preventing anything passing through it.$(br)Nearby $(thing)endermen$() can't teleport. $(item)Ender pearls$(), $(item)chorus fruits$(), $(l:spells/ender_strike)Ender strike$(), $(l:spells/translocation)translocation$(), and other teleportation methods don't work.$(br2)It consumes $(thing)water element$().");
        addPatchouliPages("breedingshrine", "The $(item)Breeding Shrine$() uses $(thing)food$() laying around to breed $(thing)animals$() in range.$(br2)It consumes $(thing)earth element$().");
        addPatchouliPages("groveshrine", "The $(item)Wild Grove Shrine$() will create wild $(thing)flowers$() on top of $(item)grass$().$(br2)It consumes $(thing)water element$().");
        addPatchouliPages("springshrine", "The $(item)Spring Shrine$() will create a water block on top of it.$(br2)It consumes $(thing)water element$().");
        addPatchouliPages("buddingshrine", "The $(item)Budding Shrine$() grows $(item)amethyst clusters$() on top of it.$(br2)It consumes $(thing)earth element$().");
        addPatchouliPages("spawningshrine", "The $(item)Spawning Shrine$() summons mobs around it.$(br2)It consumes $(thing)fire element$().");

        addPatchouliPages("shrine_upgrade_acceleration", "The $(item)Acceleration Shrine Upgrade$() doubles the speed of a shrine. It can be placed on any side including top and bottom.");
        addPatchouliPages("shrine_upgrade_range", "The $(item)Range shrine upgrade$() increases the range of a shrine at the cost of speed and increased element consumption. It can be placed on any side including top and bottom.");
        addPatchouliPages("shrine_upgrade_capacity", "The $(item)Capacity shrine upgrade$() greatly increases the capacity of a shrine at the cost of speed and increased element consumption. It can be placed on any side including top and bottom.");
        addPatchouliPages("shrine_upgrade_efficiency", "The $(item)efficiency shrine upgrade$() halves the element consumption of a shrine at the cost of a bit of capacity. It can be placed on any side including top and bottom.");
        addPatchouliPages("shrine_upgrade_optimization", "The $(item)optimization shrine upgrade$() reduces the element consumption and increases the speed and capacity of a shrine but it can only use two. It can be placed on any side including top and bottom.");
        addPatchouliPages("shrine_upgrade_strength", "The $(item)strength shrine upgrade$() doubles the strength of the effect of a shrine at the cost of increased element consumption. It can be placed on any side including top and bottom.$(br)It cannot be used in combination with a $(l:shrine_upgrades/shrine_upgrade_nectar)nectar shrine upgrade$() or a $(l:shrine_upgrades/shrine_upgrade_pickup)pickup shrine upgrade$().");
        addPatchouliPages("shrine_upgrade_fortune", "The $(item)Fortune shrine upgrade$() gives one level of fortune to a shrine up to three at the cost of increased element consumption. It can be placed on all four sides but not on top and bottom. It cannot be used in combination with a $(l:shrine_upgrades/shrine_upgrade_silk_touch)silk touch shrine upgrade$().");
        addPatchouliPages("shrine_upgrade_silk_touch", "The $(item)Silk touch shrine upgrade$() gives the silk touch effect to a shrine at the cost of increased element consumption. It can be placed on all four sides but not on top and bottom. It cannot be used in combination with a $(l:shrine_upgrades/shrine_upgrade_fortune)fortune shrine upgrade$().");
        addPatchouliPages("shrine_upgrade_planting", "The $(item)Planting shrine upgrade$() plants back harvested crops or saplings. It can only be placed on the bottom of an $(l:shrines/harvestshrine)harvest shrine$().");
        addPatchouliPages("shrine_upgrade_boneless_growth", "The $(item)Boneless growth shrine upgrade$() gives the ability to a $(l:shrines/growthshrine)growth shrine$() to grow crops that cannot grow with bone meal. It can only be placed on top of a $(l:shrines/growthshrine)growth shrine$(). It cannot be used in combination with a $(l:shrine_upgrades/shrine_upgrade_stem_pollination)stem pollination shrine upgrade$().");
        addPatchouliPages("shrine_upgrade_pickup", "The $(item)Pickup Shrine Upgrade$() is a shrine upgrade exclusive to the $(l:shrines/vacuumshrine)vacuum shrine$(). It completely changes the behavior of the $(l:shrines/vacuumshrine)vacuum shrine$(). It will instantly pick up items instead of pulling them towards it first. It can only be placed on top of the shrine. It cannot be used in combination with a $(l:shrine_upgrades/shrine_upgrade_vortex)vortex shrine upgrade$() or a $(l:shrine_upgrades/shrine_upgrade_strength)strength shrine upgrade$().");
        addPatchouliPages("shrine_upgrade_vortex", "The $(item)vortex shrine upgrade$() is a shrine upgrade exclusive to the $(l:shrines/vacuumshrine)vacuum shrine$(). It changes the shrine to pull mobs and creatures instead of items. It can only be placed on top of the shrine. It cannot be used in combination with a $(l:shrine_upgrades/shrine_upgrade_pickup)pickup shrine upgrade$().");
        addPatchouliPages("shrine_upgrade_nectar", "The $(item)nectar shrine upgrade$() is a shrine upgrade that changes a $(l:shrines/sweetshrine)sweet shrine$() to provide bees with nectar instead of feeding players. It can be placed on all four sides but not on top and bottom. It cannot be used in combination with a $(l:shrine_upgrades/shrine_upgrade_strength)strength shrine upgrade$().");
        addPatchouliPages("shrine_upgrade_stem_pollination", "The $(item)stem pollination shrine$() upgrade gives the ability to a $(l:shrines/growthshrine)growth shrine$() to mature melons or pumpkins. It can only be placed on top of a growth shrine. It cannot be used in combination with a $(l:shrine_upgrades/shrine_upgrade_boneless_growth)boneless growth shrine upgrade$().");
        addPatchouliPages("shrine_upgrade_protection", "The $(item)protection shrine upgrade$() alters a shrine that affects creatures to only affect hostile mobs. It can be placed on any side but not on top and bottom.");
        addPatchouliPages("shrine_upgrade_filling", "The $(item)filling shrine upgrade$() is a shrine upgrade exclusive to the $(l:shrines/springshrine)spring shrine$() and the $(l:shrines/melting_shrine)lava shrine$() changing the behavior of the shrine. It will instantly fill the liquid tank connected to the upgrade with fluid. It can only be placed on top of the $(l:shrines/springshrine)spring shrine$() and on the side of the $(l:shrines/melting_shrine)lava shrine$().");
        addPatchouliPages("shrine_upgrade_springaline", "The $(item)Springaline shrine upgrade$() is a shrine upgrade exclusive to the $(l:shrines/buddingshrine)budding shrine$(). It makes the budding shrine grow $(l:basics/springaline)springaline clusters$() instead of amethyst. It can be placed on any of the four sides but not on top or bottom.");
        addPatchouliPages("shrine_upgrade_crystal_harvest", "The $(item)crystal harvest shrine upgrade$() is a shrine upgrade for the $(l:shrines/buddingshrine)budding shrine$() and the $(l:shrines/oreshrine)ore shrine$(). It makes the $(l:shrines/buddingshrine)budding shrine$() automatically harvest the amethyst or $(l:basics/springaline)springaline clusters$() once fully grown. With it, the $(l:shrines/oreshrine)ore shrine$() will harvest fully grown crystals from budding blocks. It can be placed on any of the four sides but not on top or bottom.");
        addPatchouliPages("shrine_upgrade_mystical_grove", "The $(item)mystical grove shrine upgrade$() is a shrine upgrade exclusive to the $(l:shrines/wildgroveshrine)wild grove shrine$(). It is only available if Botania is present in the pack. It makes the $(l:shrines/wildgroveshrine)wild grove shrine$() grow Botania mystical flowers instead of traditional flowers. It can be placed on top.");
        addPatchouliPages("shrine_upgrade_crystal_growth", "The $(item)crystal growth shrine upgrade$() makes the $(l:shrines/growthshrine)growth shrine$() speedup the growth of budding crystals like amethyst instead of crops, this does not affect crystals that a $(l:shrines/buddingshrine)budding shrine$() is growing. It can only be placed on top of a $(l:shrines/growthshrine)growth shrine$(). It cannot be used in combination with a $(l:shrine_upgrades/shrine_upgrade_boneless_growth)boneless growth shrine upgrade$().");

        addPatchouliPages("shrine_upgrade_translocation", "The $(item)translocation shrine upgrade$() makes the $(l:shrines/growthshrine)growth shrine$() move the target location of the operation to a $(l:spells/translocation_anchor)translocation anchor$().$(br)To specify the new location first right click the anchor with the $(item)translocation shrine upgrade$() to bind it to the anchor, then place it normally on the shrine. It is an advanced shrine upgrade and as such cannot be used with other advanced shrine upgrades.");
        addPatchouliPages("shrine_upgrade_overclocked_acceleration", "The $(item)overclocked acceleration shrine upgrade$() is a more powerful version of the $(l:shrine_upgrades/shrine_upgrade_acceleration)acceleration shrine upgrade$(). You can also connect $(ec:pipe)pipes$() on its back to supply the shrine with elements. It can be placed on all four sides but not on top and bottom. It is an advanced shrine upgrade and as such cannot be used with other advanced shrine upgrades.");
        addPatchouliPages("shrine_upgrade_greater_fortune", "The $(item)Greater fortune shrine upgrade$() is a more powerful version of the $(l:shrine_upgrades/shrine_upgrade_fortune)fortune shrine upgrade$() giving 3 levels of fortune instead of one. You can get an additional level of fortune by adding a Tzeentch's rune on it. It can be placed on all four sides but not on top and bottom. It cannot be used in combination with a $(l:shrine_upgrades/shrine_upgrade_silk_touch)silk touch shrine upgrade$() or a standard $(l:shrine_upgrades/shrine_upgrade_fortune)fortune shrine upgrade$(). It is an advanced shrine upgrade and as such cannot be used with other advanced shrine upgrades.");
        addPatchouliPages("shrine_upgrade_overwhelming_strength", "The $(item)overwhelming strength shrine upgrade$() is a more powerful version of the $(l:shrine_upgrades/shrine_upgrade_strength)strength shrine upgrade$(). It can be placed on any side but not on top and bottom.$(br)It cannot be used in combination with a $(l:shrine_upgrades/shrine_upgrade_nectar)nectar shrine upgrade$() or a $(l:shrine_upgrades/shrine_upgrade_pickup)pickup shrine upgrade$(). It is an advanced shrine upgrade and as such cannot be used with other advanced shrine upgrades.");

        addPatchouliPages("spell_desk", "To craft $(thing)spells$() you need a $(item)spell desk$().$(br)To use it right-click to open the crafting interface.$(br)You then have to place a $(item)scroll paper$(), an $(item)element crystal$() of the $(thing)element$() of the spell you want and a $(l:basics/gems)gem$() of the quality you need or better.$(br)Please refers to JEI for recipes details.");
        addPatchouliPages("casting_spells",
                "Spells can be cast either from the $(thing)scroll$(), $(l:spells/focus)focus$() or a $(l:spells/staff)staff$(). The consumes $(thing)element$() from the $(ec:holder)element holder$() in your inventory, Some spells do have additional costs, please refers to the spell page to know them.",
                "You can see if you can cast a spell by looking at the check at the bottom right of the element gauge:",
                "The spell can be cast",
                "The spell is in cooldown",
                "The spell cannot be cast");
        addPatchouliPages("focus", "A $(item)focus$() can hold multiple $(thing)spells$().$(br)You can add $(thing)spells$() to it by putting the $(item)focus$() in an $(item)anvil$() with the $(item)scroll$() of the $(thing)spell$(). You can circle through $(thing)spells$() by holding shift and scrolling.");
        addPatchouliPages("staff", "You can get a $(item)staff$() from a $(item)diamond/netherite sword$() and a  $(l:spells/focus)focus$(), it will preserve the enchantment of the sword and the spells of the focus.");
        addPatchouliPages("spell_book", "The $(item)Elementalist Grimoire$() allows you to store $(thing)spells$().You can right-click it to open its inventory.");
        addPatchouliPages("fireball", "Throw a $(thing)fire ball$() in the direction you are looking.$(br)Consumes $(thing)fire$() from an $(ec:holder)element holder$().");
        addPatchouliPages("gravelfall", "Summon a column of $(item)gravel$() above the targeted $(thing)block$() or $(thing)entity$().$(br)Consumes $(thing)earth$() from an $(ec:holder)element holder$() and three $(item)gravel$().");
        addPatchouliPages("stonewall", "Summon a three by three $(thing)stone wall$() in front of you to protect you from attacks.$(br)Consumes $(thing)earth$() from an $(ec:holder)element holder$() and nine $(item)stone$().");
        addPatchouliPages("heal", "Heal you or the targeted $(thing)entity$().$(br)Consumes $(thing)water$() from an $(ec:holder)element holder$().");
        addPatchouliPages("ender_strike", "Teleport behind targeted $(thing)entity$() or closest $(thing)monster$() and strike it with increased damage. Be careful not to use it near an $(l:shrines/enderlockshrine)Ender lock shrine$().$(br)Consumes $(thing)air$() from an $(ec:holder)element holder$().");
        addPatchouliPages("item_pull", "Pull all nearby $(item)items to you.$(br)Consumes $(thing)air$() from an $(ec:holder)element holder$().");
        addPatchouliPages("animal_growth", "Fully grow targeted $(thing)animal child$().$(br)Consumes $(thing)water$() from an $(ec:holder)element holder$().");
        addPatchouliPages("tree_fall", "Cut down targeted $(thing)tree$().$(br)Consumes $(thing)earth$() from an $(ec:holder)element holder$().");
